#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);OUT=$ROOT/work/results/l4_conv3x3_relu_requant;mkdir -p "$OUT";G=$ROOT/work/upstream/chipyard_gemmini/generators/gemmini/software/gemmini-rocc-tests;S=$ROOT/work/upstream/chipyard_gemmini/sims/verilator/simulator-chipyard.harness-GemminiRocketConfig;T=$ROOT/work/toolchain/apt-riscv/usr;D=$ROOT/work/toolchain/riscv/bin/spike-dasm;R=$ROOT/scripts/run_memory_capped.sh;P=$ROOT/work/toolchain/cnn_py312/bin/python;E=$OUT/conv-baremetal;X=$OUT/conv.trace;L=$OUT/conv.log;TMP=$(mktemp -d);trap 'rm -rf "$TMP"' EXIT;ln -s "$T/bin/riscv64-unknown-elf-as" "$TMP/as";ln -s "$T/bin/riscv64-unknown-elf-ld" "$TMP/ld";C=$G/riscv-tests/benchmarks/common
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$T/bin/riscv64-unknown-elf-gcc" -B"$TMP/" -isystem "$T/lib/picolibc/riscv64-unknown-elf/include" -DPREALLOCATE=1 -DMULTITHREAD=1 -mcmodel=medany -std=gnu99 -O2 -ffast-math -fno-common -fno-builtin-printf -fno-tree-loop-distribute-patterns -march=rv64gc -Wa,-march=rv64gc -I"$G/riscv-tests" -I"$G/riscv-tests/env" -I"$G" -I"$C" -I"$ROOT/tests" -DID_STRING=l4-requant-relu -DPRINT_TILE=0 -nostdlib -nostartfiles -static -T "$C/test.ld" -DBAREMETAL=1 "$ROOT/tests/gemmini_l4_conv3x3_relu_requant.c" "$C"/*.c "$C"/*.S -lgcc -o "$E" >"$OUT/compile.log" 2>&1
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$S" +permissive +dramsim +dramsim_ini_dir="$ROOT/work/upstream/chipyard_gemmini/generators/testchipip/src/main/resources/dramsim2_ini" +max-cycles=10000000 +loadmem="$E" +verbose +permissive-off "$E" </dev/null 2> >("$D">"$X")|tee "$L"
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$P" "$ROOT/scripts/audit_l4_conv3x3_relu_requant_payload.py" --trace "$X" --run-log "$L" --elf "$E" --vectors "$ROOT/tests/vectors/gemmini_descriptor_v2_programs.json" --output "$OUT/payload_result.json"
echo L4_CONV3X3_REQUANT_RELU_PAYLOAD_GATE_PASS
